import java.util.*;

class Solution {
    public int padToMirror(String s) {
        int n = s.length();
        int[][] dp = new int[n][n];                 // dp[i][j] = inserts needed for s[i..j]
        for (int i = n - 2; i >= 0; i--) {
            for (int j = i + 1; j < n; j++) {
                if (s.charAt(i) == s.charAt(j)) {
                    dp[i][j] = (i + 1 <= j - 1) ? dp[i + 1][j - 1] : 0;   // ends already mirror
                } else {
                    dp[i][j] = 1 + Math.min(dp[i + 1][j], dp[i][j - 1]);  // add a partner for one end
                }
            }
        }
        return dp[0][n - 1];
    }
}

