class Solution:
    def padToMirror(self, s: str) -> int:
        n = len(s)
        dp = [0] * n
        for i in range(n - 2, -1, -1):
            new = [0] * n
            for j in range(i + 1, n):
                if s[i] == s[j]:
                    new[j] = dp[j - 1] if j - 1 >= i + 1 else 0
                else:
                    new[j] = 1 + min(dp[j], new[j - 1])
            dp = new
        return dp[n - 1]

